  1	import java.util.ArrayDeque;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	import java.util.Queue;
  6	
  7	class BipartiteGraph {
  8	    static ArrayList<ArrayList<Integer>> constructadj(int vertexCount, int[][] edges) {
  9	        validateInput(vertexCount, edges);
 10	
 11	        ArrayList<ArrayList<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 12	
 13	        for (int[] edge : edges) {
 14	            addUndirectedEdge(adjacencyList, edge[0], edge[1]);
 15	        }
 16	
 17	        return adjacencyList;
 18	    }
 19	
 20	    static boolean isBipartite(int vertexCount, int[][] edges) {
 21	        ArrayList<ArrayList<Integer>> adjacencyList = constructadj(vertexCount, edges);
 22	
 23	        Color[] colors = new Color[vertexCount];
 24	        Arrays.fill(colors, Color.UNCOLORED);
 25	
 26	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 27	            if (colors[vertex] == Color.UNCOLORED && !colorComponent(vertex, adjacencyList, colors)) {
 28	                return false;
 29	            }
 30	        }
 31	
 32	        return true;
 33	    }
 34	
 35	    private static boolean colorComponent(
 36	            int startVertex,
 37	            List<? extends List<Integer>> adjacencyList,
 38	            Color[] colors
 39	    ) {
 40	        Queue<Integer> queue = new ArrayDeque<>();
 41	        colors[startVertex] = Color.FIRST;
 42	        queue.offer(startVertex);
 43	
 44	        while (!queue.isEmpty()) {
 45	            int currentVertex = queue.poll();
 46	
 47	            for (int neighbor : adjacencyList.get(currentVertex)) {
 48	                if (colors[neighbor] == Color.UNCOLORED) {
 49	                    colors[neighbor] = colors[currentVertex].opposite();
 50	                    queue.offer(neighbor);
 51	                } else if (colors[neighbor] == colors[currentVertex]) {
 52	                    return false;
 53	                }
 54	            }
 55	        }
 56	
 57	        return true;
 58	    }
 59	
 60	    private static ArrayList<ArrayList<Integer>> createEmptyAdjacencyList(int vertexCount) {
 61	        ArrayList<ArrayList<Integer>> adjacencyList = new ArrayList<>();
 62	
 63	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 64	            adjacencyList.add(new ArrayList<>());
 65	        }
 66	
 67	        return adjacencyList;
 68	    }
 69	
 70	    private static void addUndirectedEdge(
 71	            ArrayList<ArrayList<Integer>> adjacencyList,
 72	            int sourceVertex,
 73	            int targetVertex
 74	    ) {
 75	        adjacencyList.get(sourceVertex).add(targetVertex);
 76	        adjacencyList.get(targetVertex).add(sourceVertex);
 77	    }
 78	
 79	    private static void validateInput(int vertexCount, int[][] edges) {
 80	        if (vertexCount < 0) {
 81	            throw new IllegalArgumentException("vertexCount must be non-negative");
 82	        }
 83	
 84	        if (edges == null) {
 85	            throw new IllegalArgumentException("edges must not be null");
 86	        }
 87	
 88	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
 89	            validateEdge(edges[edgeIndex], edgeIndex, vertexCount);
 90	        }
 91	    }
 92	
 93	    private static void validateEdge(int[] edge, int edgeIndex, int vertexCount) {
 94	        if (edge == null || edge.length != 2) {
 95	            throw new IllegalArgumentException("edge at index " + edgeIndex + " must contain exactly two vertices");
 96	        }
 97	
 98	        validateVertex(edge[0], edgeIndex, vertexCount);
 99	        validateVertex(edge[1], edgeIndex, vertexCount);
100	    }
101	
102	    private static void validateVertex(int vertex, int edgeIndex, int vertexCount) {
103	        if (vertex < 0 || vertex >= vertexCount) {
104	            throw new IllegalArgumentException(
105	                    "edge at index " + edgeIndex + " references invalid vertex " + vertex
106	            );
107	        }
108	    }
109	
110	    public static void main(String[] args) {
111	        int vertexCount = 4;
112	
113	        int[][] edges = {{0, 1}, {0, 2}, {1, 2}, {2, 3}};
114	
115	        System.out.println(isBipartite(vertexCount, edges));
116	    }
117	
118	    private enum Color {
119	        UNCOLORED,
120	        FIRST,
121	        SECOND;
122	
123	        private Color opposite() {
124	            if (this == FIRST) {
125	                return SECOND;
126	            }
127	
128	            if (this == SECOND) {
129	                return FIRST;
130	            }
131	
132	            throw new IllegalStateException("Uncolored vertices do not have an opposite color");
133	        }
134	    }
135	}
